+    private String createDescriptionFileName(String description) {
+        String retainedWord = "rule";
+        String[] words = description.split("[^A-Za-z0-9]+");
+        for (String word : words) {
+            if (word.length() >= 4) {
+                retainedWord = word;
+            }
+        }
+
+        String digest;
+        try {
+            byte[] hash = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
+            StringBuilder hex = new StringBuilder();
+            for (byte value : hash) {
+                hex.append(String.format("%02x", value & 0xff));
+            }
+            digest = hex.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+
+        String suffix = "_" + digest;
+        int retainedLength = Math.min(retainedWord.length(), 200 - suffix.length());
+        retainedLength = Math.max(retainedLength, 4);
+        return retainedWord.substring(0, retainedLength) + suffix;
+    }
