    @Override
    public List<String> getViolations(ArchRule rule) {
        String ruleDetailsFileName;
        synchronized (storeLock) {
            ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
        }
        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
        List<String> result = readLines(ruleDetailsFileName);
        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
        return result;
    }

    private List<String> readLines(String ruleDetailsFileName) {
        String violationsText = readStoreFile(ruleDetailsFileName);
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .map(this::unescape)
                .collect(toList());
    }

    private String readStoreFile(String fileName) {
        try {
            String result = new String(Files.readAllBytes(new File(storeFolder, fileName).toPath()), UTF_8);
            return ensureUnixLineBreaks(result).replace("\r", "\n");
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private FileNameMode configureFileNameMode(Properties properties) {
        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (hasConstructorFileNameStrategy && configured != null) {
            throw new StoreInitializationFailedException(String.format(
                    "Property %s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
                    FILE_NAMES_PROPERTY_NAME));
        }
        if (hasConstructorFileNameStrategy) {
            return new FileNameMode(FileNameKind.CUSTOM, constructorFileNameStrategy);
        }
        if (configured == null || "random".equals(configured)) {
            return new FileNameMode(FileNameKind.RANDOM, null);
        }
        if ("description".equals(configured)) {
            return new FileNameMode(FileNameKind.DESCRIPTION, null);
        }
        return instantiateConfiguredStrategy(configured);
    }

    private FileNameMode instantiateConfiguredStrategy(String className) {
        try {
            Class<?> configuredClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(configuredClass)) {
                throw new StoreInitializationFailedException(String.format(
                        "Configured %s does not implement %s", FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getName()));
            }
            RuleViolationFileNameStrategy strategy = (RuleViolationFileNameStrategy) configuredClass.getConstructor().newInstance();
            return new FileNameMode(FileNameKind.CUSTOM, strategy);
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (ReflectiveOperationException | LinkageError e) {
            throw new StoreInitializationFailedException(String.format(
                    "Configured %s must name a RuleViolationFileNameStrategy with a public no-argument constructor: %s",
                    FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private IntegrityMode configureIntegrityMode(Properties properties) {
        String configured = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
        if ("ignore".equals(configured)) {
            return IntegrityMode.IGNORE;
        }
        if ("repair".equals(configured)) {
            return IntegrityMode.REPAIR;
        }
        if ("fail".equals(configured)) {
            return IntegrityMode.FAIL;
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid value for %s: '%s'. Accepted values are repair, fail and ignore",
                INTEGRITY_PROPERTY_NAME, configured));
    }

    private String requireRuleFileName(String name) {
        if (name == null || name.trim().isEmpty()) {
            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy did not return a file name");
        }
        return name;
    }

    private String createDescriptionFileName(String description) {
        String retainedWord = "rule";
        String[] words = description.split("[^A-Za-z0-9]+");
        for (String word : words) {
            if (word.length() >= 4) {
                retainedWord = word;
            }
        }

        String digest;
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder hex = new StringBuilder();
            for (byte value : hash) {
                hex.append(String.format("%02x", value & 0xff));
            }
            digest = hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new StoreUpdateFailedException(e);
        }

        String suffix = "_" + digest;
        int retainedLength = Math.min(retainedWord.length(), 200 - suffix.length());
        retainedLength = Math.max(retainedLength, 4);
        return retainedWord.substring(0, retainedLength) + suffix;
    }

    private void validateSaveTarget(String description, String fileName, File target, boolean knownRule) {
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new StoreUpdateFailedException(String.format("Rule '%s' has no violation file name", description));
        }
        try {
            File canonicalFolder = storeFolder.getCanonicalFile();
            File canonicalTarget = target.getCanonicalFile();
            File canonicalIndex = getStoredRulesFile().getCanonicalFile();
            if (!isDirectChild(canonicalTarget, canonicalFolder) || canonicalTarget.equals(canonicalIndex)) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to write rule '%s' to unsafe violation file '%s'", description, fileName));
            }
            if (Files.exists(target.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                if (!Files.isRegularFile(target.toPath())) {
                    throw new StoreUpdateFailedException(String.format(
                            "Refusing to write rule '%s' over a non-regular file '%s'", description, fileName));
                }
                if (!knownRule) {
                    throw new StoreUpdateFailedException(String.format(
                            "Refusing to overwrite an existing unowned violation file '%s'", fileName));
                }
            }
            if (!knownRule && storedRules.isRecordedByAnother(description, fileName)) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to overwrite the violation file '%s' recorded by another rule", fileName));
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private void forgetRule(String description, String fileName) {
        File target = new File(storeFolder, fileName);
        validateSaveTarget(description, fileName, target, true);
        boolean sharedFile = storedRules.isRecordedByAnother(description, fileName)
                || storedRules.hasAnotherEntryForSameFile(description, target);
        if (!sharedFile) {
            deleteOwnedFile(target);
        }
        storedRules.remove(description);
        storedRules.syncFileSystem();
    }

    private void maintainIntegrity(File storedRulesFile) {
        List<IntegrityEntry> entries = storedRules.entries();
        for (IntegrityEntry entry : entries) {
            entry.derive(this, fileNameMode);
            resolve(entry, storedRulesFile);
        }

        markSharedEntries(entries);
        markCollisionsAndOccupancy(entries);
        List<File> unownedFiles = listUnownedFiles(entries, storedRulesFile);
        if (integrityMode == IntegrityMode.FAIL) {
            if (hasIntegrityIssues(entries, unownedFiles)) {
                throw new StoreInitializationFailedException(createIntegrityReport(entries, unownedFiles));
            }
            return;
        }

        boolean indexChanged = false;
        for (IntegrityEntry entry : entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                storedRules.remove(entry.description);
                indexChanged = true;
            } else if (entry.resolved) {
                deleteOwnedFile(entry.recordedFile);
                storedRules.remove(entry.description);
                indexChanged = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                moveEntry(entry);
                storedRules.setInMemory(entry.description, entry.derivedName);
                indexChanged = true;
            }
        }
        if (indexChanged) {
            storedRules.syncFileSystem();
        }
    }

    private void resolve(IntegrityEntry entry, File storedRulesFile) {
        entry.recordedFile = new File(storeFolder, entry.recordedName);
        Path recordedPath = entry.recordedFile.toPath();
        if (!Files.exists(recordedPath, LinkOption.NOFOLLOW_LINKS)) {
            entry.broken = true;
            return;
        }
        try {
            Path realPath = recordedPath.toRealPath();
            Path indexPath = storedRulesFile.toPath().toRealPath();
            entry.realPath = realPath;
            if (realPath.equals(indexPath) || !Files.isRegularFile(realPath, LinkOption.NOFOLLOW_LINKS)
                    || !isDirectChild(realPath.toFile(), storeFolder.getCanonicalFile())) {
                entry.broken = true;
                return;
            }
            entry.identity = fileIdentity(realPath);
            entry.resolved = readLinesFromPath(realPath).isEmpty();
        } catch (IOException e) {
            entry.broken = true;
        }
    }

    private List<String> readLinesFromPath(Path path) {
        try {
            String text = new String(Files.readAllBytes(path), UTF_8);
            text = ensureUnixLineBreaks(text).replace("\r", "\n");
            return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(text)
                    .map(this::unescape)
                    .collect(toList());
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void markSharedEntries(List<IntegrityEntry> entries) {
        Map<String, List<IntegrityEntry>> byRecordedName = new HashMap<>();
        Map<String, List<IntegrityEntry>> byIdentity = new HashMap<>();
        for (IntegrityEntry entry : entries) {
            byRecordedName.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
            if (entry.identity != null) {
                byIdentity.computeIfAbsent(entry.identity, ignored -> new ArrayList<>()).add(entry);
            }
        }
        markGroupsShared(byRecordedName.values());
        markGroupsShared(byIdentity.values());
    }

    private void markGroupsShared(Collection<List<IntegrityEntry>> groups) {
        for (List<IntegrityEntry> group : groups) {
            if (group.size() > 1) {
                for (IntegrityEntry entry : group) {
                    entry.shared = true;
                }
            }
        }
    }

    private void markCollisionsAndOccupancy(List<IntegrityEntry> entries) {
        Map<String, List<IntegrityEntry>> byDerivedName = new HashMap<>();
        for (IntegrityEntry entry : entries) {
            if (entry.derivedName != null) {
                byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
            }
        }
        for (List<IntegrityEntry> group : byDerivedName.values()) {
            if (group.size() > 1) {
                for (IntegrityEntry entry : group) {
                    entry.colliding = true;
                }
            }
        }
        for (IntegrityEntry entry : entries) {
            if (entry.derivedName == null) {
                continue;
            }
            entry.misplaced = !entry.derivedName.equals(entry.recordedName);
            if (entry.misplaced) {
                File destination = new File(storeFolder, entry.derivedName);
                entry.occupied = destinationExistsOrUnsafe(destination)
                        || entries.stream().anyMatch(other -> other != entry && entry.derivedName.equals(other.recordedName));
            } else {
                entry.occupied = false;
            }
        }
    }

    private boolean destinationExistsOrUnsafe(File destination) {
        try {
            if (!isDirectChild(destination.getCanonicalFile(), storeFolder.getCanonicalFile())) {
                return true;
            }
            return Files.exists(destination.toPath(), LinkOption.NOFOLLOW_LINKS);
        } catch (IOException e) {
            return true;
        }
    }

    private boolean hasIntegrityIssues(List<IntegrityEntry> entries, List<File> unownedFiles) {
        return !unownedFiles.isEmpty() || entries.stream().anyMatch(entry ->
                entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied);
    }

    private List<File> listUnownedFiles(List<IntegrityEntry> entries, File storedRulesFile) {
        Set<String> ownedIdentities = entries.stream()
                .map(entry -> entry.identity)
                .filter(identity -> identity != null)
                .collect(Collectors.toSet());
        List<File> result = new ArrayList<>();
        File[] children = storeFolder.listFiles();
        if (children == null) {
            return result;
        }
        for (File child : children) {
            if (child.getName().equals(STORED_RULES_FILE_NAME) || !child.isFile()) {
                continue;
            }
            String identity = fileIdentity(child.toPath());
            if (identity == null || !ownedIdentities.contains(identity)) {
                result.add(child);
            }
        }
        result.sort(Comparator.comparing(File::getName));
        return result;
    }

    private String createIntegrityReport(List<IntegrityEntry> entries, List<File> unownedFiles) {
        StringBuilder report = new StringBuilder("Violation store integrity check failed:\n");
        appendEntryCondition(report, "broken", entries, entry -> entry.broken);
        appendEntryCondition(report, "resolved", entries, entry -> entry.resolved);
        appendEntryCondition(report, "shared", entries, entry -> entry.shared);
        appendEntryCondition(report, "misplaced", entries, entry -> entry.misplaced);
        appendEntryCondition(report, "colliding", entries, entry -> entry.colliding);
        appendEntryCondition(report, "occupied", entries, entry -> entry.occupied);
        if (!unownedFiles.isEmpty()) {
            report.append("unowned:\n");
            unownedFiles.stream().sorted(Comparator.comparing(File::getName))
                    .forEach(file -> report.append("  ").append(file.getName()).append('\n'));
        }
        return report.toString();
    }

    private void appendEntryCondition(StringBuilder report, String condition, List<IntegrityEntry> entries,
            EntryCondition predicate) {
        List<IntegrityEntry> matching = entries.stream().filter(predicate::matches)
                .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
        if (matching.isEmpty()) {
            return;
        }
        report.append(condition).append(':').append('\n');
        for (IntegrityEntry entry : matching) {
            report.append("  ").append(entry.description).append(" -> ").append(entry.recordedName).append('\n');
        }
    }

    private void moveEntry(IntegrityEntry entry) {
        File destination = new File(storeFolder, entry.derivedName);
        Path source = entry.realPath;
        if (source == null) {
            source = entry.recordedFile.toPath();
        }
        try {
            Files.move(source, destination.toPath());
            if (Files.isSymbolicLink(entry.recordedFile.toPath())) {
                Files.deleteIfExists(entry.recordedFile.toPath());
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not move misplaced violation file for rule '%s'", entry.description), e);
        }
    }

    private void deleteOwnedFile(File file) {
        Path path = file.toPath();
        try {
            if (Files.isSymbolicLink(path)) {
                Path target = path.toRealPath();
                Files.deleteIfExists(target);
                Files.deleteIfExists(path);
            } else {
                Files.deleteIfExists(path);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not delete violation file '%s'", file.getName()), e);
        }
    }

    private String fileIdentity(Path path) {
        try {
            Path realPath = path.toRealPath();
            BasicFileAttributes attributes = Files.readAttributes(realPath, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            Object fileKey = attributes.fileKey();
            return fileKey != null ? "key:" + fileKey : "path:" + realPath;
        } catch (IOException e) {
            return null;
        }
    }

    private boolean isRegularFileDirectlyInFolder(File file) {
        try {
            return Files.isRegularFile(file.toPath(), LinkOption.NOFOLLOW_LINKS)
                    && isDirectChild(file.getCanonicalFile(), storeFolder.getCanonicalFile());
        } catch (IOException e) {
            return false;
        }
    }

    private boolean isDirectChild(File file, File folder) {
        File parent = file.getParentFile();
        return parent != null && parent.equals(folder);
    }

    private enum FileNameKind {
        RANDOM, DESCRIPTION, CUSTOM
    }

    private static final class FileNameMode {
        private final FileNameKind kind;
        private final RuleViolationFileNameStrategy strategy;

        private FileNameMode(FileNameKind kind, RuleViolationFileNameStrategy strategy) {
            this.kind = kind;
            this.strategy = strategy;
        }
    }

    private enum IntegrityMode {
        IGNORE, REPAIR, FAIL
    }

    private interface EntryCondition {
        boolean matches(IntegrityEntry entry);
    }

    private static final class IntegrityEntry {
        private final String description;
        private final String recordedName;
        private String derivedName;
        private File recordedFile;
        private Path realPath;
        private String identity;
        private boolean broken;
        private boolean resolved;
        private boolean misplaced;
        private boolean shared;
        private boolean colliding;
        private boolean occupied;

        private IntegrityEntry(String description, String recordedName) {
            this.description = description;
            this.recordedName = recordedName;
        }

        private void derive(TextFileBasedViolationStore store, FileNameMode mode) {
            if (mode.kind == FileNameKind.RANDOM) {
                return;
            }
            String name = mode.kind == FileNameKind.DESCRIPTION
                    ? store.createDescriptionFileName(description)
                    : mode.strategy.createRuleFileName(description);
            try {
                derivedName = store.requireRuleFileName(name);
            } catch (StoreUpdateFailedException e) {
                throw new StoreInitializationFailedException(String.format(
                        "RuleViolationFileNameStrategy did not return a file name for rule '%s'", description), e);
            }
        }
    }

    private static class FileSyncedProperties {
        private final File propertiesFile;
        private final Properties loadedProperties;

        FileSyncedProperties(File file) {
            propertiesFile = file;
            loadedProperties = loadRulesFrom(file);
        }

        private Properties loadRulesFrom(File file) {
            Properties result = new Properties();
            try (FileInputStream inputStream = new FileInputStream(file)) {
